const getCsv = useCallback(
  (_scope) => {
    const headers = ['Student', 'Roll', 'Campus', 'Aptitude_status', 'Aptitude_detail', 'GD_status', 'GD_detail', 'Interviews_status', 'Interviews_detail'];
    const rows = [];
    for (let i = 0; i < rows.length; i++) {
      const row = rows[i];
      rows.push([
        row.student,
        row.roll,
        row.campus,
        row.rounds.aptitude.status,
        row.rounds.aptitude.detail,
        row.rounds.gd.status,
        row.rounds.gd.detail,
        row.rounds.interviews.status,
        row.rounds.interviews.detail,
      ]);
    }
    return { headers, rows };
  },
  [rows]
);

